    EntityKindRule {
        node_kind: "static_item",
        kind: Kind::Static,
        name_field: Some("name"),
        body_field: None,
        children_field: None,
    },
    EntityKindRule {
        node_kind: "mod_item",
        kind: Kind::Mod,
        name_field: Some("name"),
        body_field: Some("body"),
        children_field: None,
    },
    EntityKindRule {
        node_kind: "type_item",
        kind: Kind::TypeAlias,
        name_field: Some("name"),
        body_field: None,
