    },
    // `type Item;` in a trait is not `type_item` (`type Item = T`).
    EntityKindRule {
        node_kind: "associated_type",
        kind: Kind::TypeAlias,
        name_field: Some("name"),
        body_field: None,
        children_field: None,
    },
    EntityKindRule {
        node_kind: "macro_definition",
        kind: Kind::Macro,
        name_field: Some("name"),
        body_field: None,
        children_field: None,
    },
    EntityKindRule {
        node_kind: "use_declaration",
        kind: Kind::Opaque,
        name_field: None,
        body_field: None,
        children_field: None,
    },
    EntityKindRule {
        node_kind: "extern_crate_declaration",
        kind: Kind::Opaque,
        name_field: None,
        body_field: None,
        children_field: None,
    },
];

fn text(src: &[u8], node: tree_sitter::Node<'_>) -> String {
    String::from_utf8_lossy(&src[node.start_byte()..node.end_byte()]).into_owned()
}

impl Lang for RustLang {
    fn language(&self) -> tree_sitter::Language {
        tree_sitter_rust::LANGUAGE.into()
    }

    fn name(&self) -> &'static str {
        "rust"
    }

    fn extensions(&self) -> &'static [&'static str] {
        &["rs"]
    }

    fn entity_kinds(&self) -> &'static [EntityKindRule] {
        ENTITY_KINDS
    }

    fn entity_name(&self, node: tree_sitter::Node<'_>, src: &[u8]) -> Option<String> {
        if node.kind() == "impl_item" {
            let ty = node.child_by_field_name("type").map(|n| text(src, n))?;
            return Some(match node.child_by_field_name("trait") {
                Some(tr) => format!("impl<{} for {ty}>", text(src, tr)),
                None => format!("impl<{ty}>"),
            });
        }
        // Opaque items are named by their text; a byte-offset fallback would give every
        // `use` below an edited line a new identity.
        if matches!(node.kind(), "use_declaration" | "extern_crate_declaration") {
            return Some(text(src, node));
        }
        ENTITY_KINDS
            .iter()
            .find(|r| r.node_kind == node.kind())
            .and_then(|r| r.name_field)
            .and_then(|f| node.child_by_field_name(f))
            .map(|n| text(src, n))
    }

    fn roles(
        &self,
        node: tree_sitter::Node<'_>,
        field: Option<&str>,
        _src: &[u8],
        _env: &Env,
    ) -> Vec<Role> {
        rust_roles(node, field)
    }

    // Macro arguments are not opaque: `vec![x]`, `matches!(k, ..)`, `format!("{x}")` use
    // the local, and renaming the binder without them does not compile (O9). Rust has
    // no node kind whose identifiers the compiler ignores.
    fn opaque_nodes(&self) -> &'static [&'static str] {
        &[]
    }

    fn commutative_parents(&self) -> &'static [CommutativeRule] {
        &[
            CommutativeRule {
                parent: None,
                only_child_kinds: None,
                except_child_kinds: Some(&[Kind::Macro]),
            },
            CommutativeRule {
                parent: Some(Kind::Mod),
                only_child_kinds: None,
                except_child_kinds: Some(&[Kind::Macro]),
            },
        ]
    }

    fn trivia_kinds(&self) -> &'static [&'static str] {
        &[
            "line_comment",
            "block_comment",
            "attribute_item",
            "inner_attribute_item",
        ]
    }

    fn literal_kinds(&self) -> &'static [&'static str] {
        &[
            "integer_literal",
            "float_literal",
            "boolean_literal",
            "true",
            "false",
            "char_literal",
            "string_literal",
            "raw_string_literal",
            "string_content",
            "escape_sequence",
        ]
    }
}

fn rust_roles(node: tree_sitter::Node<'_>, field: Option<&str>) -> Vec<Role> {
    match node.kind() {
        "function_item" | "function_signature_item" => vec![Role::Scope {
            opens: &[Namespace::Type, Namespace::Lifetime, Namespace::Value],
            barriers: &[
                Barrier {
                    ns: Namespace::Value,
                    class: BinderClass::Local,
                    when: When::Always,
                },
                Barrier {
                    ns: Namespace::Value,
                    class: BinderClass::Generic,
                    when: When::ThroughBlock,
                },
                Barrier {
                    ns: Namespace::Type,
                    class: BinderClass::Generic,
                    when: When::ThroughBlock,
                },
                Barrier {
                    ns: Namespace::Lifetime,
                    class: BinderClass::Generic,
                    when: When::ThroughBlock,
                },
                Barrier {
                    ns: Namespace::Label,
                    class: BinderClass::Label,
                    when: When::Always,
                },
            ],
        }],
        "let_declaration" => vec![Role::Binder {
            namespace: Namespace::Value,
            visibility: Visibility::AfterStmt,
            locator: Locator::Field("pattern"),
        }],
        // `if let` / `while let` / let-chains. AfterStmt covers `&& h > 1` in a
        // let-chain; `binder_extent` then ends the scope at the then-body / loop body.
        "let_condition" => vec![Role::Binder {
            namespace: Namespace::Value,
            visibility: Visibility::AfterStmt,
            locator: Locator::Field("pattern"),
        }],
        "match_arm" | "last_match_arm" => vec![Role::Binder {
            namespace: Namespace::Value,
            // pattern includes the guard; value is the arm body. Whole would
            // walk to the enclosing function block and leak the binder into
            // other arms.
            visibility: Visibility::Sub(&["pattern", "value"]),
            locator: Locator::Field("pattern"),
        }],
        "for_expression" => vec![Role::Binder {
            namespace: Namespace::Value,
            visibility: Visibility::Sub(&["body"]),
            locator: Locator::Field("pattern"),
        }],
        "parameter" => vec![Role::Binder {
            namespace: Namespace::Value,
            visibility: Visibility::Sub(&["body"]),
            locator: Locator::Field("pattern"),
        }],
        "identifier" if field == Some("name") => vec![],
        // Untyped closure parameter `|s|`: a bare identifier under closure_parameters, scoped
        // to the closure. Typed ones are `parameter` nodes and bind through their pattern; a
        // locator over all of `parameters` would also bind the type names (O9 caught that).
        "identifier"
            if node
                .parent()
                .is_some_and(|p| p.kind() == "closure_parameters") =>
        {
            vec![Role::Binder {
                namespace: Namespace::Value,
                visibility: Visibility::Whole,
                locator: Locator::Itself,
            }]
        }
        "identifier" => vec![Role::Reference {
            namespace: Namespace::Value,
        }],
        "type_identifier" => vec![Role::Reference {
            namespace: Namespace::Type,
        }],
        "lifetime" => vec![Role::Reference {
            namespace: Namespace::Lifetime,
        }],
        "label" => match node.parent().map(|p| p.kind()) {
            Some("break_expression") | Some("continue_expression") => {
                vec![Role::Reference {
                    namespace: Namespace::Label,
                }]
            }
            _ => vec![Role::Binder {
                namespace: Namespace::Label,
                visibility: Visibility::Whole,
                locator: Locator::Itself,
            }],
        },
        "block" => vec![Role::Scope {
            opens: &[
                Namespace::Type,
                Namespace::Value,
                Namespace::Macro,
                Namespace::Label,
            ],
            barriers: &[],
        }],
        "closure_expression" => vec![Role::Scope {
            opens: &[Namespace::Value],
            barriers: &[Barrier {
                ns: Namespace::Label,
                class: BinderClass::Label,
                when: When::Always,
            }],
        }],
        "type_parameter" | "lifetime_parameter" | "const_parameter" => {
            let ns = match node.kind() {
                "lifetime_parameter" => Namespace::Lifetime,
                "const_parameter" => Namespace::Value,
                _ => Namespace::Type,
            };
            vec![Role::Binder {
                namespace: ns,
                visibility: Visibility::Whole,
                locator: Locator::Field("name"),
            }]
        }
        "self_parameter" => vec![Role::Binder {
            namespace: Namespace::Value,
            visibility: Visibility::Sub(&["body"]),
            locator: Locator::Itself,
        }],
        "const_block" => vec![Role::Scope {
            opens: &[
                Namespace::Type,
                Namespace::Value,
                Namespace::Macro,
                Namespace::Label,
            ],
            barriers: &[
                Barrier {
                    ns: Namespace::Value,
                    class: BinderClass::Local,
                    when: When::Always,
                },
                Barrier {
                    ns: Namespace::Label,
                    class: BinderClass::Label,
                    when: When::Always,
                },
                Barrier {
                    ns: Namespace::Lifetime,
                    class: BinderClass::Generic,
                    when: When::Always,
                },
            ],
        }],
        "async_block" | "gen_block" => vec![Role::Scope {
            opens: &[Namespace::Value],
            barriers: &[Barrier {
                ns: Namespace::Label,
                class: BinderClass::Label,
                when: When::Always,
            }],
        }],
        _ => vec![],
    }
}

crates/svc-core/tests/o3_rename.rs.Text:
use std::collections::BTreeMap;

use svc_core::engine::{
    add_def, edit_def, ingest_file, lookup_name, redefine, rename, render, rust_langs,
    snapshot_files, status_report,
};
use svc_core::ids::{ChangeId, EntityId, RelPath};
use svc_core::store::MemStore;
use svc_core::{IdentRef, Intent, RustLang, Store, Token};

const SRC: &str = r#"fn parse(s: &str) -> usize { s.len() }
fn load(path: &str) -> usize { parse(path) }
"#;

#[test]
fn o3_rename_does_not_touch_other_hashes() {
    let store = MemStore::new();
    let lang = RustLang;
    let path = RelPath::new("src/lib.rs").unwrap();
    let snap = ingest_file(SRC.as_bytes(), path, &lang, &store, ChangeId::new()).unwrap();
    let parse_id = lookup_name(&snap, "parse").unwrap();
    let load_id = lookup_name(&snap, "load").unwrap();
    let load_before = snap.entities[&load_id].clone();
    let parse_before = snap.entities[&parse_id].clone();

    let next = rename(&store, &snap, parse_id, "parse_config").unwrap();
    let load_after = &next.entities[&load_id];
    let parse_after = &next.entities[&parse_id];

    assert_eq!(parse_after.name, "parse_config");
    assert_eq!(parse_after.content, parse_before.content);
    assert_eq!(parse_after.bytes, parse_before.bytes);
    assert_eq!(load_after.content, load_before.content);
    assert_eq!(load_after.bytes, load_before.bytes);

    let langs = rust_langs();
    let rendered = render(&next, &store, &langs, false).unwrap();
    let text = String::from_utf8(rendered.files.values().next().unwrap().clone()).unwrap();
    assert!(text.contains("fn parse_config"), "{text}");
    assert!(text.contains("parse_config(path)"), "{text}");
    assert!(!text.contains("fn parse("), "{text}");
}

#[test]
fn snapshot_files_matches_ingest_and_status_is_clean() {
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(path.clone(), SRC.as_bytes().to_vec());
    let change = ChangeId::new();
    let snap = snapshot_files(&store, &langs, &files, None, change).unwrap();
    assert!(snap.entities.values().any(|e| e.name == "parse"));
    assert!(snap.entities.values().any(|e| e.name == "load"));
    let again = snapshot_files(&store, &langs, &files, Some(&snap), change).unwrap();
    let report = status_report(&store, &snap, &again).unwrap();
    assert_eq!(
        report.summary(),
        format!("{} entities, 0 changes", snap.entities.len())
    );
}

#[test]
fn redefine_keeps_callees_as_entity_holes() {
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(path, SRC.as_bytes().to_vec());
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let load_id = lookup_name(&snap, "load").unwrap();
    let parse_id = lookup_name(&snap, "parse").unwrap();
    let text = b"fn load(path: &str) -> usize { parse(path) + 1 }\n";
    let (_, content, bytes) = redefine(&store, &langs, &snap, load_id, text).unwrap();
    let c = store.get_content(content).unwrap();
    assert!(
        c.tokens.iter().any(|t| match t {
            Token::Ident(IdentRef::Entity(id)) => *id == parse_id,
            _ => false,
        }),
        "callee must resolve to parse's entity id, got {:?}",
        c.tokens
    );
    let _ = bytes;
}

#[test]
fn layout_local_rename_is_not_semantic() {
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(path.clone(), SRC.as_bytes().to_vec());
    let change = ChangeId::new();
    let snap = snapshot_files(&store, &langs, &files, None, change).unwrap();
    let edited = SRC.replace(
        "fn parse(s: &str) -> usize { s.len() }",
        "fn parse(input: &str) -> usize { input.len() }",
    );
    files.insert(path, edited.into_bytes());
    let next = snapshot_files(&store, &langs, &files, Some(&snap), change).unwrap();
    let report = status_report(&store, &snap, &next).unwrap();
    assert_eq!(report.semantic, 0, "{:?}", report.deltas);
    assert_eq!(report.layout, 1, "{:?}", report.deltas);
}

#[test]
fn redefine_without_trailing_newline_keeps_callee_entity() {
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(path, SRC.as_bytes().to_vec());
